#!/usr/bin/env bash

########################################################################################
# DO NOT EDIT THIS FILE
# Put custom entry point tasks in the file custom_entrypoint.sh

if [ "$1" == "DOCS" ] ; then
  cat /UserDocs.md
  exit 0
fi

./custom_entrypoint.sh "$1" "$2" "$3" "$4" "$5" "$6" "$7" "$8" "$9"

if [ -f "/service_config.json" ]; then
  echo "Config found in /" >> /service/log/start.log
  cp /service_config.json /service/service_config.json
  chmod 666 /service/service_config.json
  # A weird case for some alternate containers.
fi

if [ -f "/config/service_config.json" ]; then
    echo "Config found in /config" >> /service/log/start.log
    cp /config/service_config.json /service/service_config.json
fi


if [ -f "NOSERVICE" ]; then
    echo "Not starting the service as ordered."
    while true; do sleep 100000; done
else
    echo "Starting..." >> /service/log/start.log

    if [ -f "DEBUGGER" ]; then
        DPORT=$(<DEBUGGER)

        ./debugging.sh
        wget https://go.dev/dl/go1.22.4.linux-amd64.tar.gz
        rm -rf /usr/local/go && tar -C /usr/local -xzf go1.22.4.linux-amd64.tar.gz
        export PATH=$PATH:/usr/local/go/bin
        go install github.com/go-delve/delve/cmd/dlv@latest
        cd /service
        /root/go/bin/dlv exec /service/ginfra_service.exe --log --wd /service --listen "0.0.0.0:${DPORT}" --headless --api-version=2 --accept-multiclient -- /service

    else

        cd /service
        echo "Execute ginfra_service" >> /service/log/start.log
        ./ginfra_service.exe /service $1 $2 $3 $4 $5 $6 $7 $8 $9 >> /service/log/start.log 2>&1

    fi

fi

cat /service/log/start.log
